def sample_probs(logits, T, top_p):
    p = softmax([x / T for x in logits])
    order = argsort(p, descending=True)
    keep, total = [], 0.0
    for i in order:
        keep.append(i); total += p[i]
        if total >= top_p: break
    z = sum(p[i] for i in keep)
    return {i: p[i] / z for i in keep}
